arguments.new_string:
while pos < len(text):
    char = text[pos]
    char_size = cell_size(char)

    if cell_pos + char_size >= cut:
        if cell_pos + char_size == cut:
            # Split exactly after this character
            before = text[:pos+1]
            return (
                _Segment(before, style, control),
                _Segment(text[pos+1:], style, control),
            )
        else: # cell_pos + char_size > cut
            # Split inside this character. Split before it.
            before = text[:pos]
            return (
                _Segment(before, style, control),
                _Segment(text[pos:], style, control),
            )

    cell_pos += char_size

arguments.old_string:
while pos < len(text):
    char = text[pos]
    pos += 1
    cell_pos += cell_size(char)
    before = text[:pos]
    if cell_pos == cut:
        return (
            _Segment(before, style, control),
            _Segment(text[pos:], style, control),
        )
